arguments.content:
[
  {
    "type": "function",
    "function": {
      "name": "read",
      "description": "Read file contents",
      "parameters": {
        "type": "object",
        "properties": {
          "path": {"type": "string", "description": "Path to the file to read"}
        },
        "required": ["path"]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "bash",
      "description": "Execute a bash command (ls, grep, find, etc.)",
      "parameters": {
        "type": "object",
        "properties": {
          "command": {"type": "string", "description": "The bash command to execute"}
        },
        "required": ["command"]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "edit",
      "description": "Make precise file edits with exact text replacement, including multiple disjoint edits in one call",
      "parameters": {
        "type": "object",
        "properties": {
          "path": {"type": "string", "description": "Path to the file to edit"},
          "edits": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "oldText": {"type": "string", "description": "Exact text to replace; must match the original file"},
                "newText": {"type": "string", "description": "Replacement text"}
              },
              "required": ["oldText", "newText"]
            }
          }
        },
        "required": ["path", "edits"]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "write",
      "description": "Create or overwrite a file",
      "parameters": {
        "type": "object",
        "properties": {
          "path": {"type": "string", "description": "Path of the file to write"},
          "content": {"type": "string", "description": "Full file content"}
        },
        "required": ["path", "content"]
      }
    }
  }
]
